\label{mainI}
Let $\mathcal{F}$ be the flat disk in $\mathbb F_q^n,  n=2d\ge 4,$ defined as in \eqref{DefFlat}. Then we have
$$ R^*_{\mathcal{F}} \left(2\to \frac{2n+4}{n-2}\right) =R^*_{\mathcal{F}} \left(2\to \frac{2d+2}{d-1}\right)\lesssim 1.$$

One of main ingredients to deduce Theorem \ref{mainI} is based on  the explicit Fourier transform on the surface measure $d\sigma$ of the flat disk $\mathcal{F},$ which will be given as Proposition \ref{Promain}. The key idea to compute it is to view the flat disk $\mathcal{F}$ in \eqref{DefFlat}  as the set of common solutions of the following two equations:
\begin{equation} \label{defFeq} x_d=x_1^2+x_2^2+\cdots + x_{d-1}^2, \quad  x_{2d}= x_1x_{d+1} +x_2x_{d+2} + \cdots+ x_{d-2}x_{2d-2}+ x_{d-1} x_{2d-1}.\end{equation} 
Then, adapting the argument by the discrete Fourier analysis due to Iosevich and Rudnev \cite{IR07}, we are able to relate the equations defining the flat disk to certain exponential sums, which essentially reduce to the well-understood Gauss sums.

\label{main3}
Let $\mathcal{F}$ be the flat disk in $\mathbb F_q^{2d}.$ 
\begin{enumerate}
\item [(1)] If $d=3$ and $q\equiv 3 \pmod{4},$ then  $R^*_{\mathcal{F}} \left( \frac{36-10\varepsilon}{13-5\varepsilon}\to \frac{18}{5}-\varepsilon \right) \lesssim 1$ for some $\varepsilon >0.$
\item [(2)] If $d=3$ and $q\equiv 3 \pmod{4}$ is prime,  then  $R^*_{\mathcal{F}}\left(\frac{376+106\varepsilon}{135+53\varepsilon} \to \frac{188}{53}+\varepsilon \right)\lesssim 1$ for all $\varepsilon >0.$
\item [(3)] If $d\ge 3 $ is odd and $q\equiv 1 \pmod{4},$ then  $R^*_{\mathcal{F}}\left(\frac{2d+2}{d} \to \frac{2d+2}{d-1}\right) \lesssim 1.$
\item [(4)]  If $d=  4\ell+1$ with $\ell \in \mathbb N,$ and $q\equiv 3 \pmod{4},$ then  $R^*_{\mathcal{F}}\left(\frac{2d+2}{d}  \to \frac{2d+2}{d-1}\right) \lesssim 1.$
\item [(5)]   If $d=  4\ell+3$, with $\ell \in \mathbb N,$ and $q\equiv 3 \pmod{4}, $ then  $R^*_{\mathcal{F}}\left(\frac{2d^2+2d-4}{d^2-2} \to \frac{2d+4}{d}\right) \lesssim 1.$
\end{enumerate}

\label{Kdd}
Let $K(p\to r)$ be defined as in \eqref{Kdef}. Then we have
$$ K(d\to d)\lesssim 1.$$

\label{PFK}
Let $P, \mathcal{F},$ and $K$ denote the paraboloid in $\mathbb F_q^d, d\ge 2,$   the flat disk in $\mathbb F_q^{2d},$ and  the Kakeya operator in $\mathbb F_q^d, respectively.$  Then,  for $ 2\le p, r \le \infty,$  we have
$$ R^*_{\mathcal{F}}(p\to r) \le R^*_{P}(2 \to r)  K\left( \left(\frac{r}{2}\right)' \to \left(\frac{p}{2}\right)' \right) ^{1/2}.$$

\label{mainII}
Let $\mathcal{F}$ be the flat disk in $\mathbb F_q^n,  n=2d\ge 4.$ Then the restriction estimate
 \begin{equation*} ||\widehat{g}||_{L^{2}(\mathcal{F}, d\sigma)} \lesssim ||g||_{L^{\frac{2n+4}{n+6}}(\mathbb F_q^n, dm)}\end{equation*}
holds for all functions $g$ on $\mathcal{F}$.

\label{LemFormula}
Let $P, \mathcal{F} $ denote the paraboloid in $\mathbb F_q^d, d\ge 2,$  and  the flat disk in $\mathbb F_q^{2d},$ respectively.
Suppose that $R^*_P(2\to r) \lesssim 1$ for some $\frac{2d}{d-1}\le r\le \infty.$ Then we have
\begin{equation}\label{FlatF}R^*_{\mathcal{F}}\left(\frac{2r(d-1)}{rd-r-2} \to r\right) \lesssim 1.\end{equation}

We shall invoke the following facts:
\begin{equation}\label{ResK} R^*_{\mathcal{F}}(p\to r) \le R^*_{P}(2 \to r)  K\left( \left(\frac{r}{2}\right)' \to \left(\frac{p}{2}\right)' \right) ^{1/2} \quad \mbox{for} \quad 2\le p, r\le \infty, \end{equation}
\begin{equation}\label{KaR}  K(d\to d)\lesssim 1 \quad \mbox{for all}\quad d\ge 2,\end{equation}
and
\begin{equation} \label{TrK}K(1\to \infty)\lesssim 1 \quad \mbox{for all}\quad d\ge 2.\end{equation}

The equality \eqref{ResK} is Theorem \ref{PFK} due to Mockenhaupt and Tao,  and  the estimate \eqref{KaR} is Theorem \ref{Kdd}, proven by  Ellenberg,  Oberlin, and Tao \cite{EOT10}.  The equality \eqref{TrK} is obvious as we have
$$ |f^*(v)|=\left|\sup_{m_0\in \mathbb F_q^{d-1}} \sum_{m\in \ell(m_0, v)} |f(m)|\right|\le \sum_{m\in \mathbb F_q^d} |f(m)| =||f||_{L^1(\mathbb F_q^d, dm)}.$$

Taking $p=\frac{2r(d-1)}{rd-r-2}$ in \eqref{ResK} gives us that
$$  R^*_{\mathcal{F}}\left(\frac{2r(d-1)}{rd-r-2} \to r\right) \le R^*_{P}(2 \to r)  K\left(\frac{r}{r-2}\to \frac{r(d-1)}{2} \right) ^{1/2}.$$
Since $R^*_{P}(2 \to r) \lesssim 1$ with $r\ge \frac{2d}{d-1}$ by hypothesis, to complete the proof,  it is enough to show that 
\begin{equation*} K\left( \frac{r}{r-2} \to \frac{r(d-1)}{2} \right)  \lesssim 1.\end{equation*}
But this Kakeya maximal estimate follows by interpolating the estimates \eqref{KaR} and  \eqref{TrK}. 
Thus the proof is complete.

\label{restEven}
Let $P$ be the paraboloid in $\mathbb F_q^d, d\ge 2,$ defined as in \eqref{DefP}.
Then the following estimates hold.
\begin{enumerate}
\item  $R^*_P(2\to 4)\lesssim 1 $ for $d=2.$
\item   $R^*_P\left(2\to  \frac{28}{9} \right)\lesssim 1$ for $d=4.$
\item $R^*_P(2\to 3) \lesssim 1$  if $d=4$ and $q$ is prime.
\item  $R^*_P\left(2\to  \frac{8}{3}+\varepsilon \right)\lesssim 1$ for $d=6$ and for all $\varepsilon >0.$
\item $R^*_P\left(2\to  \frac{2d+4}{d} \right)\lesssim 1$ for $d\ge 8$ even.
\end{enumerate}

\label{restOdd}
Let $P$ be the paraboloid in $\mathbb F_q^d.$ Then the following statements are valid.
\begin{enumerate}
\item [(1)] If $d=3$ and $q\equiv 3 \pmod{4},$ then  $R^*_{P} \left( 2 \to \frac{18}{5}-\varepsilon \right) \lesssim 1$ for some $\varepsilon >0.$
\item [(2)] If $d=3$ and $q\equiv 3 \pmod{4}$ is prime,  then  $R^*_{P}\left(2 \to \frac{188}{53}+\varepsilon \right)\lesssim 1$ for all $\varepsilon >0.$
\item [(3)] If $d\ge 3 $ is odd and $q\equiv 1 \pmod{4},$ then  $R^*_{P}\left(2 \to \frac{2d+2}{d-1}\right) \lesssim 1.$
\item [(4)]  If $d=  4\ell+1$ with $\ell \in \mathbb N,$ and $q\equiv 3 \pmod{4},$ then  $R^*_{P}\left(2  \to \frac{2d+2}{d-1}\right) \lesssim 1.$
\item [(5)]   If $d=  4\ell+3$, with $\ell \in \mathbb N,$ and $q\equiv 3 \pmod{4}, $ then  $R^*_{P}\left(2 \to \frac{2d+4}{d}\right) \lesssim 1.$
\end{enumerate}
